def read_submissions(text: str) -> List[Submission]:
    """Parse the submissions export (header: student_id,name,assignment,submitted_at,score)."""
    out = []
    for i, row in enumerate(_rows(text), start=2):  # data rows start at line 2
        if len(row) != 5:
            raise ValueError(f"line {i}: expected 5 fields, got {len(row)}")
        student_id, name, assignment, submitted_at, score = row
        try:
            ts = parse_timestamp(submitted_at)
        except ValueError as e:
            raise ValueError(f"line {i}: {e}")
        try:
            sc = float(score)
        except ValueError:
            raise ValueError(f"line {i}: invalid score '{score}'")
        out.append(Submission(student_id, name, assignment, ts, sc))
    return out

